#!/usr/bin/env bash
# monorepo-settings-check.sh [ROOT] -- the monorepo root's settings gate. Exit 0 clean, 1 findings
# (one `file:line: RULE message` per finding), 2 cannot run (no PyYAML, no python3).
# PYTHON=<interpreter> overrides python3. No network, no pnpm. "Unit has target T" is make's exit status for
# `make -C <unit> -q <target>`, nothing it prints. The inspection asks make -C <unit> -q <target>; only if that answers 0 does it ask make -C <unit> -q -B <target> (the same question with every file considered out of date, so the verdict does not depend on whether the unit's outputs are fresh, and with the unit's makefile named by -f and a module-owned makefile read after it that gives every makefile make has read an empty recipe, so that no makefile is remade: GNU make 3.81 remakes an included makefile that has a rule under -B and answers 1 for it, 4.3 does not); only if the last question asked answered 2 does it ask make -C <unit> -n <target> (exit status only; output discarded). Verdict: -q 1 = present; -q 0 and -q -B 1 = present (the target was only up to date), unless a file or directory named like the target sits beside the Makefile and the rule is not .PHONY (the real run says up to date: idle, with a .PHONY hint); -q -B 0 = idle (nothing to run even with everything out of date); an answer of 2 asks -n: 0 = present, 2 = missing. First question: make parses the unit's Makefile (a parse-time $(shell ...) runs; an included file that has a rule may be remade, its recipe IN FULL, plain lines too). Under -q make executes the recipe lines marked + or containing $(MAKE) of the target and of its prerequisites, each recipe at most up to its first line that is neither (an upper bound: it stops at the first out-of-date prerequisite whose recipe starts with a plain line; a file target that a + line just created may be deleted again). The -B question executes the same classes of lines, passed on to sub-makes in question mode as well, but MORE of them, since nothing counts as up to date: the + / $(MAKE) lines of prerequisites and sub-make targets that were up to date run too, and an included makefile is not remade (the pin). Under -n make walks the WHOLE recipe, so every + / $(MAKE) line of the target and of all its out-of-date prerequisites runs (a sub-make in dry-run mode runs its + lines and not its plain lines). Apart from that remake under the first question and -n, no plain recipe line runs under any question; the pin makefile runs nothing. On GNU make 3.81 and 4.3 the judgment is the same, and the same before and after a real run, for every shape measured (an included makefile that has a rule, with no rule that runs anything for the target, is idle, and so is verify: gen.mk with gen.mk such an included makefile; the same unit with verify: build or a $(MAKE) build line is present), except a recipe made only of + / $(MAKE) lines that run nothing (verify: with +true, +@echo ok, or $(MAKE) check-fast with check-fast: ;): 3.81 answers 1 to -q (present), 4.3 answers 0 to -q and to -q -B (idle, fail-closed: such a recipe verifies nothing); verify: +false differs too (3.81: -q 2 and -n 2 = missing; 4.3: -q 1 = present) and on both the root make verify ends non-zero. What runs during the inspection was measured on GNU make 3.81 and 4.3.
# (the units are the repository's own trusted code).
set -uo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
root="${1:-$(cd "$here/.." && pwd)}"
py="${PYTHON:-python3}"
# Layout guard: this module is monorepo-only (its manifest cannot say so), so a root without the pair is no monorepo.
if [[ ! -f "$root/pnpm-workspace.yaml" || ! -f "$root/repo.yaml" ]]; then
  echo "FAIL monorepo-settings-check: $root has no pnpm-workspace.yaml + repo.yaml pair; this module is for layout monorepo only"
  exit 1
fi
exec "$py" -B "$here/monorepo_check.py" check "$root"
